def verify_ref(ref):
    """'path.py:func' or 'path.py' -> (ok, detail) using the AST index."""
    if not ref or ref in ("N/A", "none"): return False, "no reference"
    f, _, fn = ref.partition(":")
    if f not in IDX: return False, f"file not found: {f}"
    if not fn or fn == "<module>": return True, f"{f} (module level)"
    for name in fn.split("/"):
        l = func_lines(IDX, f, name)
        if not l: return False, f"function not found: {f}:{name}"
    return True, "; ".join(func_lines(IDX, f, n) for n in fn.split("/"))
